use crate::lexer::Position;
use crate::values_fields::Value;
pub struct RuntimeError {
    pub position: Position,
    pub message: String
}
pub fn error(position: Position, message: &str) -> RuntimeError {
    RuntimeError {
        position,
        message: message.into()
    }
}
pub fn format(values: &[Value], position: Position) -> Result<String, RuntimeError> {
    let text = values[0].text();
    let bytes = text.as_bytes();
    let mut output = String::new();
    let mut i = 0;
    let mut argument = 1;
    while i < bytes.len() {
        if bytes[i] != b'%' {
            output.push(bytes[i] as char);
            i += 1;
            continue;
        }
        i += 1;
        if bytes.get(i) == Some(&b'%') {
            output.push('%');
            i += 1;
            continue;
        }
        let mut left = false;
        let mut zero = false;
        while bytes.get(i).map_or(false, |b| *b == b'-' || *b == b'0') {
            left |= bytes[i] == b'-';
            zero |= bytes[i] == b'0';
            i += 1;
        }
        let start = i;
        while bytes.get(i).map_or(false, |b| b.is_ascii_digit()) {
            i += 1;
        }
        let width: usize = text[start..i].parse().unwrap_or(0);
        let precision = if bytes.get(i) == Some(&b'.') {
            i += 1;
            let start = i;
            while bytes.get(i).map_or(false, |b| b.is_ascii_digit()) {
                i += 1;
            }
            Some(text[start..i].parse::<usize>().unwrap_or(0))
        } else {
            None
        };
        let conversion = *bytes.get(i).ok_or_else(|| error(position, "invalid format"))?;
        i += 1;
        if !b"dis cxo".contains(&conversion) || conversion == b' ' {
            return Err(error(position, "invalid format"));
        }
        let value = values.get(argument).ok_or_else(|| error(position, "not enough arguments"))?;
        argument += 1;
        let numeric = b"dixo".contains(&conversion);
        let mut body;
        if numeric {
            let n = value.number();
            let mut digits = match conversion {
                b'x' => format!("{:x}", n.abs()),
                b'o' => format!("{:o}", n.abs()),
                _ => n.abs().to_string()
            };
            if let Some(p) = precision {
                if p == 0 && n == 0 {
                    digits.clear();
                } else if digits.len() < p {
                    digits = "0".repeat(p - digits.len()) + &digits;
                }
            }
            body = if n < 0 {
                "-".to_string() + &digits
            } else {
                digits
            };
        } else if conversion == b's' {
            body = value.text();
            if let Some(p) = precision {
                body.truncate(p.min(body.len()));
            }
        }
        else if matches!(value, Value::Number(_) | Value::Numeric(_, _)) {
            let code = value.number();
            if code != 10 && !(32..=126).contains(&code) {
                return Err(error(position, "invalid character code"));
            }
            body = (code as u8 as char).to_string();
        } else {
            body = value.text().chars().next().map(|c| c.to_string()).unwrap_or_default();
        }
        if body.len() < width {
            let padding = width - body.len();
            if left {
                body.push_str(&" ".repeat(padding));
            }
            else if numeric && zero && precision.is_none() {
                if body.starts_with('-') {
                    body = "-".to_string() + &"0".repeat(padding) + &body[1..];
                } else {
                    body = "0".repeat(padding) + &body;
                }
            }
            else {
                body = " ".repeat(padding) + &body;
            }
        }
        output.push_str(&body);
    }
    Ok(output)
}
pub fn scalar(name: &str, values: &[Value], position: Position) -> Result<Value, RuntimeError> {
    Ok(match name {
        "substr" => {
            let text = values[0].text();
            let start = values[1].number();
            let end = if values.len() == 3 {
                start + values[2].number()
            } else {
                text.len() as i64 + 1
            };
            let start = start.max(1);
            let end = end.min(text.len() as i64 + 1);
            Value::String(if end > start {
                text[(start - 1) as usize..(end - 1) as usize].into()
            } else {
                String::new()
            })
        },
        "index" => {
            let text = values[0].text();
            let target = values[1].text();
            Value::Number(if target.is_empty() {
                0
            } else {
                text.find(&target).map_or(0, |i| (i + 1) as i64)
            })
        },
        "toupper" => Value::String(values[0].text().to_ascii_uppercase()),
        "tolower" => Value::String(values[0].text().to_ascii_lowercase()),
        "int" => Value::Number(values[0].number()),
        "sprintf" => Value::String(format(values, position)?),
        _ => unreachable!()
    })
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Position {
    pub line: usize,
    pub column: usize
}
impl Position {
    pub fn text(self) -> String {
        format!("{}:{}", self.line, self.column)
    }
}
#[derive(Clone)]
pub struct Token {
    pub kind: &'static str,
    pub text: String,
    pub value: String,
    pub position: Position
}
pub fn lex(text: &str) -> Result<Vec<Token>, Position> {
    let bytes = text.as_bytes();
    let mut result = Vec::new();
    let mut i = 0;
    let mut line = 1;
    let mut column = 1;
    while i < bytes.len() {
        let position = Position {
            line,
            column
        };
        let start = i;
        if bytes[i] == b' ' {
            i += 1;
            column += 1;
            continue;
        }
        if bytes[i] == b'\\' && bytes.get(i + 1) == Some(&b'\n') {
            i += 2;
            line += 1;
            column = 1;
            continue;
        }
        if bytes[i] == b'#' {
            while i < bytes.len() && bytes[i] != b'\n' {
                i += 1;
                column += 1;
            }
            continue;
        }
        if bytes[i] == b'\n' {
            result.push(Token {
                kind: "newline",
                text: "\n".into(),
                value: String::new(),
                position
            });
            i += 1;
            line += 1;
            column = 1;
            continue;
        }
        let kind;
        let mut value = String::new();
        if bytes[i].is_ascii_digit() {
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                i += 1;
            }
            kind = "number";
        }
        else if bytes[i].is_ascii_alphabetic() || bytes[i] == b'_' {
            i += 1;
            while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                i += 1;
            }
            let word = &text[start..i];
            kind = if ["BEGIN", "END", "function", "if", "else", "while", "for", "do", "break", "continue", "next", "exit", "return", "delete", "in", "getline", "print", "printf"].contains(&word) {
                "keyword"
            }
            else if ["length", "substr", "index", "split", "sprintf", "toupper", "tolower", "close", "int"].contains(&word) {
                "builtin"
            } else if bytes.get(i) == Some(&b'(') {
                "function"
            } else {
                "name"
            };
        } else if bytes[i] == b'"' {
            i += 1;
            loop {
                if i >= bytes.len() || bytes[i] == b'\n' {
                    return Err(position);
                }
                if bytes[i] == b'"' {
                    i += 1;
                    break;
                }
                if bytes[i] == b'\\' {
                    let escape = Position {
                        line,
                        column: column + i - start
                    };
                    i += 1;
                    let c = match bytes.get(i) {
                        Some(b'n') => '\n',
                        Some(b't') => '\t',
                        Some(b'\\') => '\\',
                        Some(b'"') => '"',
                        Some(b'/') => '/',
                        _ => return Err(escape)
                    };
                    value.push(c);
                    i += 1;
                } else {
                    value.push(bytes[i] as char);
                    i += 1;
                }
            }
            kind = "string";
        } else {
            let matched = ["+=", "-=", "*=", "/=", "%=", "^=", "==", "<=", ">=", "!=", "++", "--", "&&", "||", ">>"].iter().find(|op| text[i..].starts_with(**op));
            if let Some(op) = matched {
                i += op.len();
                kind = "symbol";
            }
            else if b"+-*/%^!><?:=()[]{};,$".contains(&bytes[i]) {
                i += 1;
                kind = "symbol";
            } else {
                return Err(position);
            }
        }
        column += i - start;
        result.push(Token {
            kind,
            text: text[start..i].into(),
            value,
            position
        });
    }
    result.push(Token {
        kind: "end",
        text: String::new(),
        value: String::new(),
        position: Position {
            line,
            column: 1
        }
    });
    Ok(result)
}

mod lexer;
mod parser;
mod values_fields;
mod builtins;
mod streams;
use std::collections::{
    BTreeMap,
    BTreeSet
};
use std::cell::RefCell;
use std::rc::Rc;
use std::fs;
use lexer::Position;
use parser::{
    Program,
    Expression,
    ExprKind,
    Statement,
    StmtKind
};
use values_fields::{
    Value,
    Fields
};
use builtins::RuntimeError;
#[derive(Clone, PartialEq, Eq, PartialOrd, Ord)]
struct Key(Option<usize>, String);
struct CallSite {
    name: String,
    arguments: Vec<Expression>,
    scope: Option<usize>,
    position: Position
}
struct Preparation {
    globals: BTreeSet<String>,
    arrays: BTreeSet<Key>,
    uses: Vec<(Key, Position)>,
    calls: Vec<CallSite>,
    lines: BTreeMap<usize,
    usize>,
    functions: BTreeMap<String,
    usize>
}
impl Preparation {
    fn key(program: &Program, scope: Option<usize>, name: &str) -> Key {
        if scope.map_or(false, |i| program.functions[i].parameters.iter().any(|p| p.0 == name)) {
            Key(scope, name.into())
        } else {
            Key(None, name.into())
        }
    }
    fn name(&mut self, program: &Program, scope: Option<usize>, name: &str, position: Position, array: bool) {
        let key = Self::key(program, scope, name);
        if key.0.is_none() {
            self.globals.insert(name.into());
        }
        if array {
            self.arrays.insert(key.clone());
        }
        self.uses.push((key, position));
    }
    fn expression(&mut self, program: &Program, scope: Option<usize>, expression: &Expression) {
        match &expression.kind {
            ExprKind::Name(name) => self.name(program, scope, name, expression.position, false),
            ExprKind::Index(name, indices) => {
                self.name(program, scope, name, expression.position, true);
                for index in indices {
                    self.expression(program, scope, index);
                }
            },
            ExprKind::Field(body) | ExprKind::Parentheses(body) | ExprKind::Unary(_, body) | ExprKind::Increment(_, _, body) => self.expression(program, scope, body),
            ExprKind::Binary(_, a, b) | ExprKind::Assignment(_, a, b) => {
                self.expression(program, scope, a);
                self.expression(program, scope, b);
            },
            ExprKind::Conditional(a, b, c) => {
                self.expression(program, scope, a);
                self.expression(program, scope, b);
                self.expression(program, scope, c);
            },
            ExprKind::In(indices, name, position) => {
                for index in indices {
                    self.expression(program, scope, index);
                }
                self.name(program, scope, name, *position, true);
            },
            ExprKind::Call(name, builtin, arguments) => {
                if !builtin {
                    self.calls.push(CallSite {
                        name: name.clone(),
                        arguments: arguments.clone(),
                        scope,
                        position: expression.position
                    });
                }
                for argument in arguments {
                    self.expression(program, scope, argument);
                }
                if *builtin && name == "split" {
                    if let ExprKind::Name(name) = &arguments[1].kind {
                        self.arrays.insert(Self::key(program, scope, name));
                    }
                }
            },
            ExprKind::Getline(target, file) => {
                if let Some(target) = target {
                    self.expression(program, scope, target);
                }
                if let Some(file) = file {
                    self.expression(program, scope, file);
                }
            },
            _ => ()
        }
    }
    fn statement(&mut self, program: &Program, scope: Option<usize>, statement: &Statement) {
        if !matches!(statement.kind, StmtKind::Block(_) | StmtKind::Empty) {
            self.lines.entry(statement.position.line).or_insert(0);
        }
        match &statement.kind {
            StmtKind::Block(statements) => for statement in statements {
                self.statement(program, scope, statement);
            },
            StmtKind::Expression(expression) => self.expression(program, scope, expression),
            StmtKind::If(condition, yes, no) => {
                self.expression(program, scope, condition);
                self.statement(program, scope, yes);
                if let Some(no) = no {
                    self.statement(program, scope, no);
                }
            },
            StmtKind::While(condition, body) => {
                self.expression(program, scope, condition);
                self.statement(program, scope, body);
            },
            StmtKind::Do(body, condition) => {
                self.statement(program, scope, body);
                self.expression(program, scope, condition);
            },
            StmtKind::For(init, condition, update, body) => {
                for expression in [init, condition, update].iter().filter_map(|e| e.as_ref()) {
                    self.expression(program, scope, expression);
                }
                self.statement(program, scope, body);
            },
            StmtKind::ForIn(variable, vp, array, ap, body) => {
                self.name(program, scope, variable, *vp, false);
                self.name(program, scope, array, *ap, true);
                self.statement(program, scope, body);
            },
            StmtKind::Output(_, arguments, redirect) => {
                for argument in arguments {
                    self.expression(program, scope, argument);
                }
                if let Some((_, target, _)) = redirect {
                    self.expression(program, scope, target);
                }
            },
            StmtKind::Delete(name, position, indices) => {
                self.name(program, scope, name, *position, true);
                if let Some(indices) = indices {
                    for index in indices {
                        self.expression(program, scope, index);
                    }
                }
            },
            StmtKind::Exit(value) | StmtKind::Return(value) => if let Some(value) = value {
                self.expression(program, scope, value);
            },
            _ => ()
        }
    }
    fn analyze(program: &Program) -> Result<Self,
    (Position, String)> {
        let mut prep = Self {
            globals: ["FILENAME", "FNR", "FS", "NF", "NR", "OFS", "ORS", "SUBSEP"].iter().map(|s| s.to_string()).collect(),
            arrays: BTreeSet::new(),
            uses: Vec::new(),
            calls: Vec::new(),
            lines: BTreeMap::new(),
            functions: BTreeMap::new()
        };
        let mut errors = Vec::new();
        for (i, function) in program.functions.iter().enumerate() {
            if prep.functions.contains_key(&function.name) {
                errors.push((function.position, 0, format!("function {} redefined", function.name)));
            } else {
                prep.functions.insert(function.name.clone(), i);
            }
            let mut parameters = BTreeSet::new();
            for (name, position) in &function.parameters {
                if !parameters.insert(name.clone()) {
                    errors.push((*position, 1, format!("duplicate parameter {}", name)));
                }
                prep.uses.push((Key(Some(i), name.clone()), *position));
            }
            prep.statement(program, Some(i), &function.body);
        }
        for rule in &program.rules {
            if let Some(start) = &rule.start {
                prep.expression(program, None, start);
            }
            if let Some(end) = &rule.end {
                prep.expression(program, None, end);
            }
            if let Some(action) = &rule.action {
                prep.statement(program, None, action);
            }
        }
        for (key, position) in &prep.uses {
            if prep.functions.contains_key(&key.1) {
                errors.push((*position, 2, format!("function {} used as variable", key.1)));
            }
        }
        let mut links = Vec::new();
        for call in &prep.calls {
            if let Some(&callee) = prep.functions.get(&call.name) {
                let parameters = &program.functions[callee].parameters;
                if call.arguments.len() > parameters.len() {
                    errors.push((call.position, 4, format!("too many arguments to {}", call.name)));
                }
                for (argument, parameter) in call.arguments.iter().zip(parameters) {
                    if let ExprKind::Name(name) = &argument.kind {
                        links.push((Self::key(program, call.scope, name), Key(Some(callee), parameter.0.clone())));
                    }
                }
            } else {
                errors.push((call.position, 3, format!("undefined function {}", call.name)));
            }
        }
        if !errors.is_empty() {
            errors.sort_by_key(|e| (e.0, e.1));
            let (position, _, message) = errors.remove(0);
            return Err((position, message));
        }
        loop {
            let mut changed = false;
            for (a, b) in &links {
                if prep.arrays.contains(a) || prep.arrays.contains(b) {
                    changed |= prep.arrays.insert(a.clone());
                    changed |= prep.arrays.insert(b.clone());
                }
            }
            if !changed {
                break;
            }
        }
        Ok(prep)
    }
}
type Array = Rc<RefCell<BTreeMap<String, Value>>>;
#[derive(Clone)]
enum Cell {
    Scalar(Value),
    Array(Array)
}
enum Location {
    Variable(Option<usize>, String),
    Element(Array, String),
    Field(usize)
}
enum Flow {
    Runtime(RuntimeError),
    Next,
    Exit,
    Return(Value),
    Break,
    Continue
}
impl From<RuntimeError> for Flow {
    fn from(error: RuntimeError) -> Self {
        Self::Runtime(error)
    }
}
type Evaluation<T> = Result<T, Flow>;
struct Runtime<'a> {
    program: &'a Program,
    preparation: Preparation,
    globals: BTreeMap<String,
    Cell>,
    locals: Vec<BTreeMap<String,
    Cell>>,
    fields: Fields,
    streams: streams::Streams,
    arguments: streams::Arguments,
    operand: usize,
    current: Option<(usize, Vec<String>, usize)>,
    phase: &'static str,
    status: i64,
    rules: Vec<usize>,
    ranges: Vec<bool>,
    calls: Vec<usize>,
    active: Vec<usize>,
    depths: Vec<usize>,
}
impl<'a> Runtime<'a> {
    fn new(program: &'a Program, preparation: Preparation, arguments: streams::Arguments) -> Self {
        let mut globals = BTreeMap::new();
        for name in &preparation.globals {
            let cell = if preparation.arrays.contains(&Key(None, name.clone())) {
                Cell::Array(Rc::new(RefCell::new(BTreeMap::new())))
            } else {
                Cell::Scalar(Value::Uninitialized)
            };
            globals.insert(name.clone(), cell);
        }
        for (name, value) in [("FS", Value::String(" ".into())), ("OFS", Value::String(" ".into())), ("ORS", Value::String("\n".into())), ("SUBSEP", Value::String("\x1c".into())), ("NR", Value::Number(0)), ("FNR", Value::Number(0)), ("FILENAME", Value::String(String::new()))].iter().cloned() {
            globals.insert(name.into(), Cell::Scalar(value));
        }
        Self {
            program,
            preparation,
            globals,
            locals: Vec::new(),
            fields: Fields::new(),
            streams: streams::Streams::new(),
            arguments,
            operand: 0,
            current: None,
            phase: "BEGIN",
            status: 0,
            rules: vec![0; program.rules.len()],
            ranges: vec![false; program.rules.len()],
            calls: vec![0; program.functions.len()],
            active: vec![0; program.functions.len()],
            depths: vec![0; program.functions.len()]
        }
    }
    fn variable(&self, name: &str) -> Option<usize> {
        if self.locals.last().map_or(false, |local| local.contains_key(name)) {
            Some(self.locals.len() - 1)
        } else {
            None
        }
    }
    fn cell(&self, frame: Option<usize>, name: &str) -> Option<&Cell> {
        if let Some(frame) = frame {
            self.locals[frame].get(name)
        } else {
            self.globals.get(name)
        }
    }
    fn array(&mut self, name: &str) -> Array {
        let frame = self.variable(name);
        if let Some(Cell::Array(array)) = self.cell(frame, name) {
            return array.clone();
        }
        unreachable!()
    }
    fn value(&self, frame: Option<usize>, name: &str) -> Value {
        if frame.is_none() && name == "NF" {
            return Value::Number(self.fields.fields.len() as i64);
        }
        match self.cell(frame, name) {
            Some(Cell::Scalar(value)) => value.clone(),
            None => Value::Uninitialized,
            _ => unreachable!()
        }
    }
    fn global(&self, name: &str) -> Value {
        self.value(None, name)
    }
    fn key(&mut self, expressions: &[Expression]) -> Evaluation<String> {
        let mut keys = Vec::new();
        for expression in expressions {
            keys.push(self.expression(expression)?.text());
        }
        Ok(keys.join(&self.global("SUBSEP").text()))
    }
    fn location(&mut self, expression: &Expression) -> Evaluation<Location> {
        match &expression.kind {
            ExprKind::Name(name) => Ok(Location::Variable(self.variable(name), name.clone())),
            ExprKind::Index(name, indices) => {
                let key = self.key(indices)?;
                Ok(Location::Element(self.array(name), key))
            },
            ExprKind::Field(index) => {
                let index = self.expression(index)?.number();
                if index < 0 {
                    return Err(builtins::error(expression.position, "negative field index").into());
                }
                Ok(Location::Field(index as usize))
            },
            _ => unreachable!()
        }
    }
    fn read(&mut self, location: &Location) -> Value {
        match location {
            Location::Variable(frame, name) => self.value(*frame, name),
            Location::Element(array, key) => array.borrow_mut().entry(key.clone()).or_insert(Value::Uninitialized).clone(),
            Location::Field(index) => self.fields.get(*index)
        }
    }
    fn store(&mut self, location: &Location, value: Value, position: Position) -> Evaluation<Value> {
        match location {
            Location::Variable(frame, name) => {
                if frame.is_none() && name == "NF" {
                    let n = value.number();
                    if n < 0 {
                        return Err(builtins::error(position, "negative NF").into());
                    }
                    let ofs = self.global("OFS").text();
                    self.fields.nf(n as usize, &ofs);
                }
                else if let Some(frame) = frame {
                    self.locals[*frame].insert(name.clone(), Cell::Scalar(value));
                }
                else {
                    self.preparation.globals.insert(name.clone());
                    self.globals.insert(name.clone(), Cell::Scalar(value));
                }
            },
            Location::Element(array, key) => {
                array.borrow_mut().insert(key.clone(), value);
            },
            Location::Field(index) => {
                let fs = self.global("FS").text();
                let ofs = self.global("OFS").text();
                self.fields.assign(*index, value, &fs, &ofs);
            }
        }
        Ok(self.read(location))
    }
    fn arithmetic(&self, op: &str, a: i64, b: i64, position: Position) -> Evaluation<Value> {
        if (op == "/" || op == "%") && b == 0 {
            return Err(builtins::error(position, "division by zero").into());
        }
        if op == "^" && b < 0 {
            return Err(builtins::error(position, "negative exponent").into());
        }
        Ok(Value::Number(match op {
            "+" => a + b,
            "-" => a - b,
            "*" => a * b,
            "/" => a / b,
            "%" => a % b,
            "^" => {
                let mut result = 1;
                let mut base = a;
                let mut exponent = b;
                while exponent > 0 {
                    if exponent % 2 == 1 {
                        result *= base;
                    }
                    exponent /= 2;
                    if exponent > 0 {
                        base *= base;
                    }
                }
                result
            },
            _ => unreachable!()
        }))
    }
    fn expression(&mut self, expression: &Expression) -> Evaluation<Value> {
        let position = expression.position;
        match &expression.kind {
            ExprKind::Number(n) => Ok(Value::Number(*n)),
            ExprKind::String(s) => Ok(Value::String(s.clone())),
            ExprKind::Name(_) | ExprKind::Index(_, _) | ExprKind::Field(_) => {
                let location = self.location(expression)?;
                Ok(self.read(&location))
            },
            ExprKind::Parentheses(body) => self.expression(body),
            ExprKind::Unary(op, body) => {
                let value = self.expression(body)?;
                Ok(Value::Number(match op.as_str() {
                    "-" => -value.number(),
                    "+" => value.number(),
                    _ => if value.truth() {
                        0
                    } else {
                        1
                    }
                }))
            },
            ExprKind::Binary(op, left, right) => {
                let a = self.expression(left)?;
                if op == "||" && a.truth() {
                    return Ok(Value::Number(1));
                }
                if op == "&&" && !a.truth() {
                    return Ok(Value::Number(0));
                }
                let b = self.expression(right)?;
                if op == "||" || op == "&&" {
                    return Ok(Value::Number(if b.truth() {
                        1
                    } else {
                        0
                    }));
                }
                if op == "concat" {
                    return Ok(Value::String(a.text() + &b.text()));
                }
                if ["<", "<=", "==", "!=", ">=", ">"].contains(&op.as_str()) {
                    let order = a.compare(&b);
                    let result = match op.as_str() {
                        "<" => order.is_lt(),
                        "<=" => !order.is_gt(),
                        "==" => order.is_eq(),
                        "!=" => !order.is_eq(),
                        ">=" => !order.is_lt(),
                        _ => order.is_gt()
                    };
                    return Ok(Value::Number(if result {
                        1
                    } else {
                        0
                    }));
                }
                self.arithmetic(op, a.number(), b.number(), position)
            },
            ExprKind::Assignment(op, target, right) => {
                let location = self.location(target)?;
                let b = self.expression(right)?;
                let value = if op == "=" {
                    b
                } else {
                    let a = self.read(&location);
                    self.arithmetic(&op[..1], a.number(), b.number(), position)?
                };
                self.store(&location, value, position)
            },
            ExprKind::Increment(delta, prefix, target) => {
                let location = self.location(target)?;
                let value = self.read(&location).number();
                self.store(&location, Value::Number(value + delta), position)?;
                Ok(Value::Number(if *prefix {
                    value + delta
                } else {
                    value
                }))
            },
            ExprKind::Conditional(condition, yes, no) => if self.expression(condition)?.truth() {
                self.expression(yes)
            } else {
                self.expression(no)
            },
            ExprKind::In(indices, name, _) => {
                let key = self.key(indices)?;
                let contains = self.array(name).borrow().contains_key(&key);
                Ok(Value::Number(if contains {
                    1
                } else {
                    0
                }))
            },
            ExprKind::Call(name, builtin, arguments) => if *builtin {
                self.builtin(name, arguments, position)
            } else {
                self.call(name, arguments)
            },
            ExprKind::Getline(target, file) => {
                let (status, line) = if let Some(file) = file {
                    let name = self.expression(file)?.text();
                    self.streams.getline(&name)
                } else if self.phase == "END" {
                    (0, None)
                } else {
                    match self.next_record()? {
                        Some(line) => (1, Some(line)),
                        None => (0, None)
                    }
                };
                if let Some(line) = line {
                    if let Some(target) = target {
                        let location = self.location(target)?;
                        self.store(&location, Value::input(line), position)?;
                    } else {
                        let fs = self.global("FS").text();
                        self.fields.set(line, &fs);
                    }
                }
                Ok(Value::Number(status))
            }
        }
    }
    fn builtin(&mut self, name: &str, arguments: &[Expression], position: Position) -> Evaluation<Value> {
        if name == "length" {
            if arguments.is_empty() {
                return Ok(Value::Number(self.fields.record.text().len() as i64));
            }
            if let ExprKind::Name(name) = &arguments[0].kind {
                let frame = self.variable(name);
                if let Some(Cell::Array(array)) = self.cell(frame, name) {
                    return Ok(Value::Number(array.borrow().len() as i64));
                }
            }
            return Ok(Value::Number(self.expression(&arguments[0])?.text().len() as i64));
        }
        if name == "split" {
            let text = self.expression(&arguments[0])?.text();
            let separator = if arguments.len() == 3 {
                self.expression(&arguments[2])?.text()
            } else {
                self.global("FS").text()
            };
            let array_name = if let ExprKind::Name(name) = &arguments[1].kind {
                name
            } else {
                unreachable!()
            };
            let array = self.array(array_name);
            let pieces = values_fields::split(&text, &separator);
            let count = pieces.len();
            let mut array = array.borrow_mut();
            array.clear();
            for (i, piece) in pieces.into_iter().enumerate() {
                array.insert((i + 1).to_string(), Value::input(piece));
            }
            return Ok(Value::Number(count as i64));
        }
        let mut values = Vec::new();
        for argument in arguments {
            values.push(self.expression(argument)?);
        }
        if name == "close" {
            return Ok(Value::Number(self.streams.close(&values[0].text())));
        }
        Ok(builtins::scalar(name, &values, position)?)
    }
    fn call(&mut self, name: &str, arguments: &[Expression]) -> Evaluation<Value> {
        let index = self.preparation.functions[name];
        let function = self.program.functions[index].clone();
        let mut local = BTreeMap::new();
        for (i, (name, _)) in function.parameters.iter().enumerate() {
            let cell = if self.preparation.arrays.contains(&Key(Some(index), name.clone())) {
                if let Some(argument) = arguments.get(i) {
                    let name = if let ExprKind::Name(name) = &argument.kind {
                        name
                    } else {
                        unreachable!()
                    };
                    Cell::Array(self.array(name))
                } else {
                    Cell::Array(Rc::new(RefCell::new(BTreeMap::new())))
                }
            } else {
                Cell::Scalar(if let Some(argument) = arguments.get(i) {
                    self.expression(argument)?
                } else {
                    Value::Uninitialized
                })
            };
            local.insert(name.clone(), cell);
        }
        self.calls[index] += 1;
        self.active[index] += 1;
        self.depths[index] = self.depths[index].max(self.active[index]);
        self.locals.push(local);
        let result = self.statement(&function.body);
        self.locals.pop();
        self.active[index] -= 1;
        match result {
            Ok(()) => Ok(Value::Uninitialized),
            Err(Flow::Return(value)) => Ok(value),
            Err(flow) => Err(flow)
        }
    }
    fn output(&mut self, printf: bool, arguments: &[Expression], redirect: &Option<(bool, Expression, Position)>, position: Position) -> Evaluation<()> {
        let mut values = Vec::new();
        for argument in arguments {
            values.push(self.expression(argument)?);
        }
        let text = if printf {
            builtins::format(&values, position)?
        } else {
            if values.is_empty() {
                values.push(self.fields.record.clone());
            }
            values.iter().map(Value::text).collect::<Vec<_>>().join(&self.global("OFS").text()) + &self.global("ORS").text()
        };
        if let Some((append, target, position)) = redirect {
            let name = self.expression(target)?.text();
            if !streams::valid_name(&name) || name == "stdout.txt" || name == "stats.txt" {
                return Err(builtins::error(*position, "invalid output file name").into());
            }
            self.streams.output(Some(&name), *append, &text);
        } else {
            self.streams.output(None, false, &text);
        }
        Ok(())
    }
    fn statement(&mut self, statement: &Statement) -> Evaluation<()> {
        let position = statement.position;
        if !matches!(statement.kind, StmtKind::Block(_) | StmtKind::Empty) {
            *self.preparation.lines.get_mut(&position.line).unwrap() += 1;
        }
        match &statement.kind {
            StmtKind::Block(statements) => for statement in statements {
                self.statement(statement)?;
            },
            StmtKind::Empty => (),
            StmtKind::Expression(expression) => {
                self.expression(expression)?;
            },
            StmtKind::If(condition, yes, no) => if self.expression(condition)?.truth() {
                self.statement(yes)?;
            } else if let Some(no) = no {
                self.statement(no)?;
            },
            StmtKind::While(condition, body) => while self.expression(condition)?.truth() {
                match self.statement(body) {
                    Ok(()) | Err(Flow::Continue) => (),
                    Err(Flow::Break) => break,
                    Err(flow) => return Err(flow)
                }
            },
            StmtKind::Do(body, condition) => loop {
                match self.statement(body) {
                    Ok(()) | Err(Flow::Continue) => (),
                    Err(Flow::Break) => break,
                    Err(flow) => return Err(flow)
                }
                if !self.expression(condition)?.truth() {
                    break;
                }
            },
            StmtKind::For(init, condition, update, body) => {
                if let Some(init) = init {
                    self.expression(init)?;
                }
                loop {
                    if let Some(condition) = condition {
                        if !self.expression(condition)?.truth() {
                            break;
                        }
                    }
                    match self.statement(body) {
                        Ok(()) | Err(Flow::Continue) => (),
                        Err(Flow::Break) => break,
                        Err(flow) => return Err(flow)
                    }
                    if let Some(update) = update {
                        self.expression(update)?;
                    }
                }
            },
            StmtKind::ForIn(variable, vp, array, _, body) => {
                let mut keys: Vec<String> = self.array(array).borrow().keys().cloned().collect();
                keys.sort_by(|a, b| values_fields::key_order(a, b));
                for key in keys {
                    let location = Location::Variable(self.variable(variable), variable.clone());
                    self.store(&location, Value::input(key), *vp)?;
                    match self.statement(body) {
                        Ok(()) | Err(Flow::Continue) => (),
                        Err(Flow::Break) => break,
                        Err(flow) => return Err(flow)
                    }
                }
            },
            StmtKind::Output(printf, arguments, redirect) => self.output(*printf, arguments, redirect, position)?,
            StmtKind::Delete(name, _, indices) => {
                let key = if let Some(indices) = indices {
                    Some(self.key(indices)?)
                } else {
                    None
                };
                let array = self.array(name);
                if let Some(key) = key {
                    array.borrow_mut().remove(&key);
                } else {
                    array.borrow_mut().clear();
                }
            },
            StmtKind::Next => {
                if self.phase == "BEGIN" || self.phase == "END" {
                    return Err(builtins::error(position, "next used in BEGIN or END").into());
                }
                return Err(Flow::Next);
            },
            StmtKind::Break => return Err(Flow::Break),
            StmtKind::Continue => return Err(Flow::Continue),
            StmtKind::Exit(value) => {
                if let Some(value) = value {
                    self.status = self.expression(value)?.number();
                }
                return Err(Flow::Exit);
            },
            StmtKind::Return(value) => return Err(Flow::Return(if let Some(value) = value {
                self.expression(value)?
            } else {
                Value::Uninitialized
            }))
        }
        Ok(())
    }
    fn next_record(&mut self) -> Evaluation<Option<String>> {
        loop {
            if let Some((file, lines, position)) = &mut self.current {
                if *position < lines.len() {
                    let line = lines[*position].clone();
                    *position += 1;
                    self.arguments.files[*file].1 += 1;
                    let nr = self.global("NR").number() + 1;
                    let fnr = self.global("FNR").number() + 1;
                    self.globals.insert("NR".into(), Cell::Scalar(Value::Number(nr)));
                    self.globals.insert("FNR".into(), Cell::Scalar(Value::Number(fnr)));
                    return Ok(Some(line));
                }
            }
            let operand = match self.arguments.operands.get(self.operand) {
                Some(operand) => operand.clone(),
                None => return Ok(None)
            };
            self.operand += 1;
            match operand {
                streams::Operand::Assignment(name, value) => {
                    self.preparation.globals.insert(name.clone());
                    self.globals.insert(name, Cell::Scalar(Value::input(value)));
                },
                streams::Operand::File(name, index) => {
                    self.globals.insert("FILENAME".into(), Cell::Scalar(Value::String(name.clone())));
                    self.globals.insert("FNR".into(), Cell::Scalar(Value::Number(0)));
                    self.current = Some((index, streams::read_file(&name).unwrap(), 0));
                }
            }
        }
    }
    fn execute(&mut self) -> Evaluation<()> {
        for (name, value) in self.arguments.options.clone() {
            self.preparation.globals.insert(name.clone());
            self.globals.insert(name, Cell::Scalar(Value::input(value)));
        }
        let mut exiting = false;
        for i in 0..self.program.rules.len() {
            let rule = self.program.rules[i].clone();
            if rule.kind == "BEGIN" {
                self.rules[i] += 1;
                match self.statement(rule.action.as_ref().unwrap()) {
                    Err(Flow::Exit) => {
                        exiting = true;
                        break;
                    },
                    result => result?
                }
            }
        }
        self.phase = "rules";
        if !exiting && self.program.rules.iter().any(|r| r.kind != "BEGIN") {
            'records: while let Some(record) = self.next_record()? {
                let fs = self.global("FS").text();
                self.fields.set(record, &fs);
                for i in 0..self.program.rules.len() {
                    let rule = self.program.rules[i].clone();
                    if rule.kind == "BEGIN" || rule.kind == "END" {
                        continue;
                    }
                    let tested: Evaluation<bool> = (|| {
                        Ok(if rule.kind == "all" {
                            true
                        } else if rule.kind == "range" {
                            if !self.ranges[i] && self.expression(rule.start.as_ref().unwrap())?.truth() {
                                self.ranges[i] = true;
                            }
                            let matched = self.ranges[i];
                            if matched && self.expression(rule.end.as_ref().unwrap())?.truth() {
                                self.ranges[i] = false;
                            }
                            matched
                        } else {
                            self.expression(rule.start.as_ref().unwrap())?.truth()
                        })
                    })();
                    let matched = match tested {
                        Ok(matched) => matched,
                        Err(Flow::Next) => continue 'records,
                        Err(Flow::Exit) => break 'records,
                        Err(flow) => return Err(flow)
                    };
                    if matched {
                        self.rules[i] += 1;
                        let result = if let Some(action) = &rule.action {
                            self.statement(action)
                        } else {
                            let text = self.fields.record.text() + &self.global("ORS").text();
                            self.streams.output(None, false, &text);
                            Ok(())
                        };
                        match result {
                            Err(Flow::Next) => continue 'records,
                            Err(Flow::Exit) => break 'records,
                            result => result?
                        }
                    }
                }
            }
        }
        self.phase = "END";
        for i in 0..self.program.rules.len() {
            let rule = self.program.rules[i].clone();
            if rule.kind == "END" {
                self.rules[i] += 1;
                match self.statement(rule.action.as_ref().unwrap()) {
                    Err(Flow::Exit) => break,
                    result => result?
                }
            }
        }
        Ok(())
    }
    fn report(&self, status: String) {
        self.streams.save();
        let mut lines = vec![status, "[inputs]".into()];
        for (name, count) in &self.arguments.files {
            lines.push(format!("{} records={}", name, count));
        }
        lines.push("[getline]".into());
        for input in &self.streams.inputs {
            lines.push(if input.opened {
                format!("{} reads={}", input.name, input.reads)
            } else {
                format!("{} missing", input.name)
            });
        }
        lines.push("[rules]".into());
        for (i, rule) in self.program.rules.iter().enumerate() {
            lines.push(format!("{} {} count={}", rule.position.text(), rule.kind, self.rules[i]));
        }
        lines.push("[functions]".into());
        for (i, function) in self.program.functions.iter().enumerate() {
            lines.push(format!("{} calls={} depth={}", function.name, self.calls[i], self.depths[i]));
        }
        lines.push("[outputs]".into());
        lines.push(format!("stdout.txt writes={} bytes={}", self.streams.writes, self.streams.stdout.len()));
        for output in &self.streams.outputs {
            lines.push(format!("{} writes={} bytes={}", output.name, output.writes, output.text.len()));
        }
        lines.push("[lines]".into());
        for (line, count) in &self.preparation.lines {
            lines.push(format!("{} count={}", line, count));
        }
        lines.push("[globals]".into());
        for name in &self.preparation.globals {
            let value = match self.globals.get(name) {
                Some(Cell::Array(array)) => format!("array ({})", array.borrow().len()),
                _ => self.global(name).display()
            };
            lines.push(format!("{} = {}", name, value));
        }
        save_stats(&lines);
    }
}
fn save_stats(lines: &[String]) {
    fs::create_dir_all("output").unwrap();
    fs::write("output/stats.txt", lines.join("\n") + "\n").unwrap();
}
fn failure(status: String) {
    fs::create_dir_all("output").unwrap();
    fs::write("output/stdout.txt", "").unwrap();
    save_stats(&[status]);
}
fn main() {
    let source = fs::read_to_string("input/program.awk").unwrap();
    let program = match lexer::lex(&source).and_then(parser::parse) {
        Ok(program) => program,
        Err(position) => {
            failure(format!("status: syntax error at {}", position.text()));
            return;
        }
    };
    let preparation = match Preparation::analyze(&program) {
        Ok(preparation) => preparation,
        Err((position, message)) => {
            failure(format!("status: error at {}: {}", position.text(), message));
            return;
        }
    };
    let arguments = streams::arguments(&fs::read_to_string("input/args.txt").unwrap());
    let mut runtime = Runtime::new(&program, preparation, arguments);
    let status = match runtime.execute() {
        Err(Flow::Runtime(error)) => format!("status: runtime error at {}: {}", error.position.text(), error.message),
        _ => format!("status: exit {}", runtime.status)
    };
    runtime.report(status);
}

use crate::lexer::{
    Token,
    Position
};
#[derive(Clone)]
pub struct Expression {
    pub position: Position,
    pub kind: ExprKind
}
#[derive(Clone)]
pub enum ExprKind {
    Number(i64),
    String(String),
    Name(String),
    Index(String, Vec<Expression>),
    Field(Box<Expression>),
    Parentheses(Box<Expression>),
    Unary(String, Box<Expression>),
    Binary(String, Box<Expression>, Box<Expression>),
    Assignment(String, Box<Expression>, Box<Expression>),
    Increment(i64, bool, Box<Expression>),
    Conditional(Box<Expression>, Box<Expression>, Box<Expression>),
    In(Vec<Expression>, String, Position),
    Call(String, bool, Vec<Expression>),
    Getline(Option<Box<Expression>>, Option<Box<Expression>>),
}
impl Expression {
    pub fn lvalue(&self) -> bool {
        matches!(self.kind, ExprKind::Name(_) | ExprKind::Index(_, _) | ExprKind::Field(_))
    }
}
#[derive(Clone)]
pub struct Statement {
    pub position: Position,
    pub kind: StmtKind
}
#[derive(Clone)]
pub enum StmtKind {
    Block(Vec<Statement>),
    Empty,
    Expression(Expression),
    If(Expression, Box<Statement>, Option<Box<Statement>>),
    While(Expression, Box<Statement>),
    Do(Box<Statement>, Expression),
    For(Option<Expression>, Option<Expression>, Option<Expression>, Box<Statement>),
    ForIn(String, Position, String, Position, Box<Statement>),
    Output(bool, Vec<Expression>, Option<(bool, Expression, Position)>),
    Delete(String, Position, Option<Vec<Expression>>),
    Next,
    Break,
    Continue,
    Exit(Option<Expression>),
    Return(Option<Expression>),
}
#[derive(Clone)]
pub struct Function {
    pub name: String,
    pub position: Position,
    pub parameters: Vec<(String, Position)>,
    pub body: Statement
}
#[derive(Clone)]
pub struct Rule {
    pub kind: &'static str,
    pub position: Position,
    pub start: Option<Expression>,
    pub end: Option<Expression>,
    pub action: Option<Statement>
}
pub struct Program {
    pub rules: Vec<Rule>,
    pub functions: Vec<Function>
}
struct Parser {
    tokens: Vec<Token>,
    index: usize,
    function: bool,
    special: bool,
    loops: usize
}
type Result<T> = std::result::Result<T, Position>;
impl Parser {
    fn peek(&self) -> &Token {
        &self.tokens[self.index]
    }
    fn text(&self) -> &str {
        &self.peek().text
    }
    fn take(&mut self) -> Token {
        let token = self.peek().clone();
        if token.kind != "end" {
            self.index += 1;
        }
        token
    }
    fn expect(&mut self, text: &str) -> Result<Token> {
        if self.text() == text && self.peek().kind != "end" {
            Ok(self.take())
        } else {
            Err(self.peek().position)
        }
    }
    fn name(&mut self) -> Result<Token> {
        if self.peek().kind == "name" {
            Ok(self.take())
        } else {
            Err(self.peek().position)
        }
    }
    fn newlines(&mut self) {
        while self.peek().kind == "newline" {
            self.take();
        }
    }
    fn terminator(&mut self) -> Result<()> {
        if self.text() == ";" || self.peek().kind == "newline" {
            self.take();
            Ok(())
        } else if self.text() == "}" {
            Ok(())
        } else {
            Err(self.peek().position)
        }
    }
    fn expressions(&mut self, suppress: bool) -> Result<Vec<Expression>> {
        let mut expressions = vec![self.expression(suppress)?];
        while self.text() == "," {
            self.take();
            self.newlines();
            expressions.push(self.expression(suppress)?);
        }
        Ok(expressions)
    }
    fn expression(&mut self, suppress: bool) -> Result<Expression> {
        let left = self.conditional(suppress)?;
        if left.lvalue() && ["=", "+=", "-=", "*=", "/=", "%=", "^="].contains(&self.text()) {
            let token = self.take();
            let right = self.expression(suppress)?;
            Ok(Expression {
                position: token.position,
                kind: ExprKind::Assignment(token.text, Box::new(left), Box::new(right))
            })
        } else {
            Ok(left)
        }
    }
    fn conditional(&mut self, suppress: bool) -> Result<Expression> {
        let condition = self.binary(1, suppress)?;
        if self.text() == "?" {
            let token = self.take();
            let yes = self.conditional(suppress)?;
            self.expect(":")?;
            let no = self.conditional(suppress)?;
            Ok(Expression {
                position: token.position,
                kind: ExprKind::Conditional(Box::new(condition), Box::new(yes), Box::new(no))
            })
        } else {
            Ok(condition)
        }
    }
    fn binary(&mut self, minimum: usize, suppress: bool) -> Result<Expression> {
        let mut left = self.unary(suppress)?;
        loop {
            let explicit = match self.text() {
                "||" => 1,
                "&&" => 2,
                "in" => 3,
                "<" | "<=" | "==" | "!=" | ">=" => 4,
                ">" if !suppress => 4,
                "+" | "-" => 6,
                "*" | "/" | "%" => 7,
                _ => 0
            };
            let concat = explicit == 0 && (["number", "string", "name", "function", "builtin"].contains(&self.peek().kind) || ["$", "(", "++", "--"].contains(&self.text()));
            let precedence = if concat {
                5
            } else {
                explicit
            };
            if precedence == 0 || precedence < minimum {
                break;
            }
            if explicit == 3 {
                let token = self.take();
                let name = self.name()?;
                left = Expression {
                    position: token.position,
                    kind: ExprKind::In(vec![left], name.text, name.position)
                };
                continue;
            }
            let position = self.peek().position;
            let operator = if concat {
                "concat".to_string()
            } else {
                self.take().text
            };
            if operator == "||" || operator == "&&" {
                self.newlines();
            }
            let right = self.binary(precedence + 1, suppress)?;
            left = Expression {
                position,
                kind: ExprKind::Binary(operator, Box::new(left), Box::new(right))
            };
        }
        Ok(left)
    }
    fn unary(&mut self, suppress: bool) -> Result<Expression> {
        if ["!", "-", "+"].contains(&self.text()) {
            let token = self.take();
            let body = self.unary(suppress)?;
            return Ok(Expression {
                position: token.position,
                kind: ExprKind::Unary(token.text, Box::new(body))
            });
        }
        let left = self.postfix(suppress)?;
        if self.text() == "^" {
            let token = self.take();
            let right = self.unary(suppress)?;
            Ok(Expression {
                position: token.position,
                kind: ExprKind::Binary(token.text, Box::new(left), Box::new(right))
            })
        } else {
            Ok(left)
        }
    }
    fn prefix(&mut self, suppress: bool) -> Result<Expression> {
        let token = self.take();
        let lvalue = self.lvalue(suppress)?;
        Ok(Expression {
            position: token.position,
            kind: ExprKind::Increment(if token.text == "++" {
                1
            } else {
                -1
            }, true, Box::new(lvalue))
        })
    }
    fn postfix(&mut self, suppress: bool) -> Result<Expression> {
        if self.text() == "++" || self.text() == "--" {
            return self.prefix(suppress);
        }
        let body = self.atom(suppress)?;
        if body.lvalue() && (self.text() == "++" || self.text() == "--") {
            let token = self.take();
            Ok(Expression {
                position: token.position,
                kind: ExprKind::Increment(if token.text == "++" {
                    1
                } else {
                    -1
                }, false, Box::new(body))
            })
        } else {
            Ok(body)
        }
    }
    fn lvalue(&mut self, suppress: bool) -> Result<Expression> {
        if self.peek().kind != "name" && self.text() != "$" {
            return Err(self.peek().position);
        }
        self.atom(suppress)
    }
    fn atom(&mut self, suppress: bool) -> Result<Expression> {
        let token = self.peek().clone();
        let position = token.position;
        let kind = match token.kind {
            "number" => {
                self.take();
                ExprKind::Number(token.text.parse().unwrap())
            },
            "string" => {
                self.take();
                ExprKind::String(token.value)
            },
            "name" => {
                self.take();
                if self.text() == "[" {
                    self.take();
                    let indices = self.expressions(false)?;
                    self.expect("]")?;
                    ExprKind::Index(token.text, indices)
                } else {
                    ExprKind::Name(token.text)
                }
            },
            "function" | "builtin" => {
                self.take();
                let builtin = token.kind == "builtin";
                let mut arguments = Vec::new();
                if self.text() == "(" {
                    self.take();
                    if self.text() != ")" {
                        arguments = self.expressions(false)?;
                    }
                    self.expect(")")?;
                }
                else if !builtin || token.text != "length" {
                    return Err(self.peek().position);
                }
                if builtin {
                    let n = arguments.len();
                    let valid = match token.text.as_str() {
                        "length" => n <= 1,
                        "substr" => n == 2 || n == 3,
                        "index" => n == 2,
                        "split" => (n == 2 || n == 3) && matches!(arguments[1].kind, ExprKind::Name(_)),
                        "sprintf" => n >= 1,
                        _ => n == 1
                    };
                    if !valid {
                        return Err(position);
                    }
                }
                ExprKind::Call(token.text, builtin, arguments)
            },
            _ => match token.text.as_str() {
                "$" => {
                    self.take();
                    let field = if self.text() == "++" || self.text() == "--" {
                        self.prefix(suppress)?
                    } else {
                        self.atom(suppress)?
                    };
                    ExprKind::Field(Box::new(field))
                },
                "(" => {
                    self.take();
                    let expressions = self.expressions(false)?;
                    self.expect(")")?;
                    if expressions.len() == 1 {
                        ExprKind::Parentheses(Box::new(expressions.into_iter().next().unwrap()))
                    }
                    else {
                        self.expect("in")?;
                        let name = self.name()?;
                        ExprKind::In(expressions, name.text, name.position)
                    }
                },
                "getline" => {
                    self.take();
                    let target = if self.peek().kind == "name" || self.text() == "$" {
                        Some(Box::new(self.lvalue(suppress)?))
                    } else {
                        None
                    };
                    let file = if self.text() == "<" {
                        self.take();
                        Some(Box::new(self.atom(suppress)?))
                    } else {
                        None
                    };
                    ExprKind::Getline(target, file)
                },
                _ => return Err(position)
            }
        };
        Ok(Expression {
            position,
            kind
        })
    }
    fn block(&mut self) -> Result<Statement> {
        let position = self.expect("{")?.position;
        let mut statements = Vec::new();
        while self.text() != "}" {
            if self.peek().kind == "newline" || self.text() == ";" {
                self.take();
            } else {
                statements.push(self.statement()?);
            }
        }
        self.expect("}")?;
        Ok(Statement {
            position,
            kind: StmtKind::Block(statements)
        })
    }
    fn loop_body(&mut self) -> Result<Box<Statement>> {
        self.newlines();
        self.loops += 1;
        let body = self.statement()?;
        self.loops -= 1;
        Ok(Box::new(body))
    }
    fn statement(&mut self) -> Result<Statement> {
        let token = self.peek().clone();
        let position = token.position;
        let kind;
        match token.text.as_str() {
            "{" => return self.block(),
            ";" => {
                self.take();
                return Ok(Statement {
                    position,
                    kind: StmtKind::Empty
                });
            },
            "if" => {
                self.take();
                self.expect("(")?;
                let condition = self.expression(false)?;
                self.expect(")")?;
                self.newlines();
                let yes = Box::new(self.statement()?);
                self.newlines();
                let no = if self.text() == "else" {
                    self.take();
                    self.newlines();
                    Some(Box::new(self.statement()?))
                } else {
                    None
                };
                return Ok(Statement {
                    position,
                    kind: StmtKind::If(condition, yes, no)
                });
            },
            "while" => {
                self.take();
                self.expect("(")?;
                let condition = self.expression(false)?;
                self.expect(")")?;
                let body = self.loop_body()?;
                return Ok(Statement {
                    position,
                    kind: StmtKind::While(condition, body)
                });
            },
            "do" => {
                self.take();
                let body = self.loop_body()?;
                self.newlines();
                self.expect("while")?;
                self.expect("(")?;
                let condition = self.expression(false)?;
                self.expect(")")?;
                kind = StmtKind::Do(body, condition);
            },
            "for" => {
                self.take();
                self.expect("(")?;
                let for_in = self.tokens.get(self.index).map_or(false, |t| t.kind == "name") && self.tokens.get(self.index + 1).map_or(false, |t| t.text == "in") && self.tokens.get(self.index + 2).map_or(false, |t| t.kind == "name") && self.tokens.get(self.index + 3).map_or(false, |t| t.text == ")");
                if for_in {
                    let variable = self.name()?;
                    self.take();
                    let array = self.name()?;
                    self.take();
                    let body = self.loop_body()?;
                    return Ok(Statement {
                        position,
                        kind: StmtKind::ForIn(variable.text, variable.position, array.text, array.position, body)
                    });
                }
                let init = if self.text() == ";" {
                    None
                } else {
                    Some(self.expression(false)?)
                };
                self.expect(";")?;
                self.newlines();
                let condition = if self.text() == ";" {
                    None
                } else {
                    Some(self.expression(false)?)
                };
                self.expect(";")?;
                self.newlines();
                let update = if self.text() == ")" {
                    None
                } else {
                    Some(self.expression(false)?)
                };
                self.expect(")")?;
                let body = self.loop_body()?;
                return Ok(Statement {
                    position,
                    kind: StmtKind::For(init, condition, update, body)
                });
            },
            "print" | "printf" => {
                self.take();
                let printf = token.text == "printf";
                let empty = [";", "\n", "}", ">", ">>"].contains(&self.text());
                let mut parenthesized = false;
                if self.text() == "(" {
                    let mut depth = 0;
                    for i in self.index..self.tokens.len() {
                        if self.tokens[i].text == "(" {
                            depth += 1;
                        } else if self.tokens[i].text == ")" {
                            depth -= 1;
                            if depth == 0 {
                                parenthesized = self.tokens.get(i + 1).map_or(false, |t| [";", "\n", "}", ">", ">>"].contains(&t.text.as_str()) || t.kind == "end");
                                break;
                            }
                        }
                    }
                }
                if empty && printf {
                    return Err(self.peek().position);
                }
                let arguments = if empty {
                    Vec::new()
                } else if parenthesized {
                    self.take();
                    let arguments = self.expressions(false)?;
                    self.expect(")")?;
                    arguments
                } else {
                    self.expressions(true)?
                };
                let redirect = if self.text() == ">" || self.text() == ">>" {
                    let op = self.take();
                    Some((op.text == ">>", self.binary(5, false)?, op.position))
                } else {
                    None
                };
                kind = StmtKind::Output(printf, arguments, redirect);
            },
            "delete" => {
                self.take();
                let name = self.name()?;
                let indices = if self.text() == "[" {
                    self.take();
                    let indices = self.expressions(false)?;
                    self.expect("]")?;
                    Some(indices)
                } else {
                    None
                };
                kind = StmtKind::Delete(name.text, name.position, indices);
            },
            "next" => {
                self.take();
                if self.special && !self.function {
                    return Err(position);
                }
                kind = StmtKind::Next;
            },
            "break" | "continue" => {
                self.take();
                if self.loops == 0 {
                    return Err(position);
                }
                kind = if token.text == "break" {
                    StmtKind::Break
                } else {
                    StmtKind::Continue
                };
            },
            "exit" | "return" => {
                self.take();
                if token.text == "return" && !self.function {
                    return Err(position);
                }
                let value = if [";", "\n", "}"].contains(&self.text()) {
                    None
                } else {
                    Some(self.expression(false)?)
                };
                kind = if token.text == "exit" {
                    StmtKind::Exit(value)
                } else {
                    StmtKind::Return(value)
                };
            },
            _ => kind = StmtKind::Expression(self.expression(false)?)
        }
        self.terminator()?;
        Ok(Statement {
            position,
            kind
        })
    }
}
pub fn parse(tokens: Vec<Token>) -> Result<Program> {
    let mut parser = Parser {
        tokens,
        index: 0,
        function: false,
        special: false,
        loops: 0
    };
    let mut program = Program {
        rules: Vec::new(),
        functions: Vec::new()
    };
    while parser.peek().kind != "end" {
        if parser.text() == ";" || parser.peek().kind == "newline" {
            parser.take();
            continue;
        }
        let position = parser.peek().position;
        if parser.text() == "function" {
            parser.take();
            if parser.peek().kind != "name" && parser.peek().kind != "function" {
                return Err(parser.peek().position);
            }
            let name = parser.take();
            parser.expect("(")?;
            let mut parameters = Vec::new();
            if parser.text() != ")" {
                loop {
                    let parameter = parser.name()?;
                    parameters.push((parameter.text, parameter.position));
                    if parser.text() != "," {
                        break;
                    }
                    parser.take();
                    parser.newlines();
                }
            }
            parser.expect(")")?;
            parser.newlines();
            parser.function = true;
            let body = parser.block()?;
            parser.function = false;
            program.functions.push(Function {
                name: name.text,
                position: name.position,
                parameters,
                body
            });
        } else if parser.text() == "BEGIN" || parser.text() == "END" {
            let begin = parser.take().text == "BEGIN";
            parser.special = true;
            let action = parser.block()?;
            parser.special = false;
            program.rules.push(Rule {
                kind: if begin {
                    "BEGIN"
                } else {
                    "END"
                },
                position,
                start: None,
                end: None,
                action: Some(action)
            });
        } else if parser.text() == "{" {
            let action = parser.block()?;
            program.rules.push(Rule {
                kind: "all",
                position,
                start: None,
                end: None,
                action: Some(action)
            });
        }
        else {
            let start = parser.expression(false)?;
            let end = if parser.text() == "," {
                parser.take();
                parser.newlines();
                Some(parser.expression(false)?)
            } else {
                None
            };
            let action = if parser.text() == "{" {
                Some(parser.block()?)
            } else {
                if parser.text() != ";" && parser.peek().kind != "newline" && parser.peek().kind != "end" {
                    return Err(parser.peek().position);
                }
                None
            };
            program.rules.push(Rule {
                kind: if end.is_some() {
                    "range"
                } else {
                    "pattern"
                },
                position,
                start: Some(start),
                end,
                action
            });
        }
    }
    Ok(program)
}

use std::fs;
#[derive(Clone)]
pub enum Operand {
    Assignment(String, String),
    File(String, usize)
}
pub struct Arguments {
    pub options: Vec<(String, String)>,
    pub operands: Vec<Operand>,
    pub files: Vec<(String, usize)>
}
pub fn valid_name(text: &str) -> bool {
    !text.is_empty() && !text.starts_with('.') && text.bytes().all(|b| b.is_ascii_alphanumeric() || b"._-".contains(&b))
}
fn variable(text: &str) -> bool {
    !text.is_empty() && (text.as_bytes()[0].is_ascii_alphabetic() || text.as_bytes()[0] == b'_') && text.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_')
}
pub fn arguments(text: &str) -> Arguments {
    let mut arguments = Arguments {
        options: Vec::new(),
        operands: Vec::new(),
        files: Vec::new()
    };
    for line in text.lines() {
        if let Some(value) = line.strip_prefix("-F ") {
            arguments.options.push(("FS".into(), value.into()));
        }
        else if let Some(value) = line.strip_prefix("-v ") {
            let (name, value) = value.split_once('=').unwrap();
            arguments.options.push((name.into(), value.into()));
        }
        else if let Some((name, value)) = line.split_once('=').filter(|(name, _)| variable(name)) {
            arguments.operands.push(Operand::Assignment(name.into(), value.into()));
        }
        else {
            let i = arguments.files.len();
            arguments.files.push((line.into(), 0));
            arguments.operands.push(Operand::File(line.into(), i));
        }
    }
    arguments
}
pub struct Output {
    pub name: String,
    pub text: String,
    pub writes: usize,
    pub open: bool
}
pub struct Input {
    pub name: String,
    pub lines: Option<Vec<String>>,
    pub position: usize,
    pub reads: usize,
    pub opened: bool,
    pub open: bool
}
pub struct Streams {
    pub stdout: String,
    pub writes: usize,
    pub outputs: Vec<Output>,
    pub inputs: Vec<Input>
}
pub fn read_file(name: &str) -> Option<Vec<String>> {
    if !valid_name(name) {
        return None;
    }
    fs::read_to_string(format!("input/{}", name)).ok().map(|s| s.lines().map(str::to_string).collect())
}
impl Streams {
    pub fn new() -> Self {
        Self {
            stdout: String::new(),
            writes: 0,
            outputs: Vec::new(),
            inputs: Vec::new()
        }
    }
    pub fn output(&mut self, name: Option<&str>, append: bool, text: &str) {
        if let Some(name) = name {
            let index = match self.outputs.iter().position(|o| o.name == name) {
                Some(i) => i,
                None => {
                    self.outputs.push(Output {
                        name: name.into(),
                        text: String::new(),
                        writes: 0,
                        open: false
                    });
                    self.outputs.len() - 1
                }
            };
            let output = &mut self.outputs[index];
            if !output.open {
                output.open = true;
                if !append {
                    output.text.clear();
                }
            }
            output.text.push_str(text);
            output.writes += 1;
        } else {
            self.stdout.push_str(text);
            self.writes += 1;
        }
    }
    pub fn getline(&mut self, name: &str) -> (i64, Option<String>) {
        let index = match self.inputs.iter().position(|i| i.name == name) {
            Some(i) => i,
            None => {
                self.inputs.push(Input {
                    name: name.into(),
                    lines: None,
                    position: 0,
                    reads: 0,
                    opened: false,
                    open: false
                });
                self.inputs.len() - 1
            }
        };
        let input = &mut self.inputs[index];
        if !input.open {
            input.lines = read_file(name);
            input.position = 0;
            if input.lines.is_some() {
                input.open = true;
                input.opened = true;
            }
        }
        if let Some(lines) = &input.lines {
            if input.position < lines.len() {
                let line = lines[input.position].clone();
                input.position += 1;
                input.reads += 1;
                (1, Some(line))
            } else {
                (0, None)
            }
        } else {
            (-1, None)
        }
    }
    pub fn close(&mut self, name: &str) -> i64 {
        let mut closed = false;
        if let Some(output) = self.outputs.iter_mut().find(|o| o.name == name) {
            closed |= output.open;
            output.open = false;
        }
        if let Some(input) = self.inputs.iter_mut().find(|i| i.name == name) {
            closed |= input.open;
            input.open = false;
        }
        if closed {
            0
        } else {
            -1
        }
    }
    pub fn save(&self) {
        fs::create_dir_all("output").unwrap();
        fs::write("output/stdout.txt", &self.stdout).unwrap();
        for output in &self.outputs {
            fs::write(format!("output/{}", output.name), &output.text).unwrap();
        }
    }
}

use std::cmp::Ordering;
#[derive(Clone)]
pub enum Value {
    Number(i64),
    String(String),
    Numeric(String, i64),
    Uninitialized
}
fn whitespace(c: char) -> bool {
    c == ' ' || c == '\t' || c == '\n'
}
impl Value {
    pub fn input(text: String) -> Self {
        let trimmed = text.trim_matches(whitespace);
        let digits = trimmed.strip_prefix('+').or_else(|| trimmed.strip_prefix('-')).unwrap_or(trimmed);
        if !digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit()) {
            let number = Self::String(text.clone()).number();
            Self::Numeric(text, number)
        } else {
            Self::String(text)
        }
    }
    pub fn number(&self) -> i64 {
        match self {
            Self::Number(n) | Self::Numeric(_, n) => *n,
            Self::Uninitialized => 0,
            Self::String(text) => {
                let text = text.trim_start_matches(whitespace);
                let negative = text.starts_with('-');
                let text = text.strip_prefix('+').or_else(|| text.strip_prefix('-')).unwrap_or(text);
                let digits: String = text.chars().take_while(|c| c.is_ascii_digit()).collect();
                let number = digits.parse::<i64>().unwrap_or(0);
                if negative {
                    -number
                } else {
                    number
                }
            }
        }
    }
    pub fn text(&self) -> String {
        match self {
            Self::Number(n) => n.to_string(),
            Self::String(s) | Self::Numeric(s, _) => s.clone(),
            Self::Uninitialized => String::new()
        }
    }
    pub fn truth(&self) -> bool {
        match self {
            Self::String(s) => !s.is_empty(),
            _ => self.number() != 0
        }
    }
    pub fn compare(&self, other: &Self) -> Ordering {
        if !matches!(self, Self::String(_)) && !matches!(other, Self::String(_)) {
            self.number().cmp(&other.number())
        } else {
            self.text().cmp(&other.text())
        }
    }
    pub fn display(&self) -> String {
        match self {
            Self::Number(n) => n.to_string(),
            Self::String(s) => quote(s),
            Self::Numeric(s, _) => format!("{} (strnum)", quote(s)),
            Self::Uninitialized => "(uninitialized)".into()
        }
    }
}
pub fn quote(text: &str) -> String {
    let mut result = String::from("\"");
    for b in text.bytes() {
        match b {
            b'"' => result.push_str("\\\""),
            b'\\' => result.push_str("\\\\"),
            10 => result.push_str("\\n"),
            9 => result.push_str("\\t"),
            32..=126 => result.push(b as char),
            _ => result.push_str(&format!("\\{:03o}", b))
        }
    }
    result.push('"');
    result
}
pub fn split(text: &str, separator: &str) -> Vec<String> {
    if separator == " " {
        text.split(whitespace).filter(|s| !s.is_empty()).map(str::to_string).collect()
    }
    else if separator.is_empty() {
        text.chars().map(|c| c.to_string()).collect()
    }
    else if text.is_empty() {
        Vec::new()
    } else {
        text.split(separator).map(str::to_string).collect()
    }
}
pub fn integer_key(text: &str) -> Option<i64> {
    if text == "0" {
        return Some(0);
    }
    let digits = text.strip_prefix('-').unwrap_or(text);
    if !digits.is_empty() && digits.as_bytes()[0] >= b'1' && digits.as_bytes()[0] <= b'9' && digits.bytes().all(|b| b.is_ascii_digit()) {
        text.parse().ok()
    } else {
        None
    }
}
pub fn key_order(a: &str, b: &str) -> Ordering {
    match (integer_key(a), integer_key(b)) {
        (Some(a), Some(b)) => a.cmp(&b),
        (Some(_), None) => Ordering::Less,
        (None, Some(_)) => Ordering::Greater,
        _ => a.cmp(b)
    }
}
pub struct Fields {
    pub record: Value,
    pub fields: Vec<Value>
}
impl Fields {
    pub fn new() -> Self {
        Self {
            record: Value::String(String::new()),
            fields: Vec::new()
        }
    }
    pub fn set(&mut self, text: String, separator: &str) {
        self.record = Value::input(text.clone());
        self.fields = split(&text, separator).into_iter().map(Value::input).collect();
    }
    pub fn get(&self, index: usize) -> Value {
        if index == 0 {
            self.record.clone()
        } else {
            self.fields.get(index - 1).cloned().unwrap_or(Value::Uninitialized)
        }
    }
    pub fn rebuild(&mut self, separator: &str) {
        self.record = Value::input(self.fields.iter().map(Value::text).collect::<Vec<_>>().join(separator));
    }
    pub fn assign(&mut self, index: usize, value: Value, fs: &str, ofs: &str) {
        if index == 0 {
            self.set(value.text(), fs);
        } else {
            if index > self.fields.len() {
                self.fields.resize(index, Value::String(String::new()));
            }
            self.fields[index - 1] = value;
            self.rebuild(ofs);
        }
    }
    pub fn nf(&mut self, size: usize, ofs: &str) {
        self.fields.resize(size, Value::String(String::new()));
        self.rebuild(ofs);
    }
}
